$ErrorActionPreference='Continue';$Root=Split-Path -Parent $PSScriptRoot;. "$PSScriptRoot/local-runtime-common.ps1";Import-SigovEnv "$Root/.env.local";Assert-SigovVariables;$checks=@();$critical=0;$warnings=0
function Add($n,$s,$d=''){script:$checks+=@([ordered]@{name=$n;status=$s;detail=$d});if($s -eq 'Error'){script:$critical++}elseif($s -eq 'Warning'){script:$warnings++}}
function Check-Http($n,$u,$optional=$false){try{$r=Invoke-WebRequest $u -TimeoutSec 8 -UseBasicParsing;Add $n 'OK' "HTTP $($r.StatusCode)"}catch{Add $n $(if($optional){'Warning'}else{'Error'}) 'endpoint indisponível'}}
Check-Http 'API live' "$env:SIGOV_API_URL/api/health/live";Check-Http 'API ready' "$env:SIGOV_API_URL/api/health/ready";Check-Http 'Web home' $env:SIGOV_WEB_URL;Check-Http 'Swagger' "$env:SIGOV_API_URL/swagger" $true
try{Invoke-RuntimePsql 'select 1'|Out-Null;Add 'Conexão runtime' 'OK';$facts=Invoke-RuntimePsql "select exists(select 1 from information_schema.schemata where schema_name='sigov')||'|'||exists(select 1 from sigov.tenant)||'|'||exists(select 1 from sigov.usuario where lower(login)='admin')";if("$facts" -match '^t\|t\|t'){Add 'Schema, tenant e admin' 'OK'}else{Add 'Schema, tenant e admin' 'Error' "$facts"}}catch{Add 'Banco runtime' 'Error' $_.Exception.Message}
if($env:SIGOV_MIGRATION_MODE -eq 'Disabled' -and $env:SIGOV_RUN_MIGRATIONS -ne 'true'){Add 'Migrations automáticas' 'OK' 'Disabled'}else{Add 'Migrations automáticas' 'Warning' "Mode=$env:SIGOV_MIGRATION_MODE"}
$leak=$false;Get-ChildItem "$Root/.local/logs" -File -ErrorAction SilentlyContinue|ForEach-Object{if($env:SIGOV_DB_PASSWORD -and (Select-String -SimpleMatch $env:SIGOV_DB_PASSWORD $_ -Quiet)){$leak=$true}};Add 'Secrets nos logs' $(if($leak){'Error'}else{'OK'})
$result=[ordered]@{timestamp=(Get-Date).ToUniversalTime().ToString('o');status=if($critical){'Critical'}elseif($warnings){'Warning'}else{'OK'};checks=$checks};$dir="$Root/artifacts/local-setup";Write-SafeJson $result "$dir/runtime-check-result.json";$checks|ConvertTo-Json -Depth 4|Set-Content "$dir/runtime-check.log";@('# Runtime check SIGOV+','',"Status: **$($result.status)**",'','| Verificação | Status | Detalhe |','|---|---|---|')+@($checks|ForEach-Object{"| $($_.name) | $($_.status) | $($_.detail) |"})|Set-Content "$dir/runtime-check-report.md";if($critical){exit 2}elseif($warnings){exit 1}else{exit 0}
